    <section class="admin-card wide"><div class="admin-card-heading"><div><h2>Akun Admin</h2><p>Admin nonaktif tidak dapat masuk dashboard.</p></div></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Nama</th><th>Email</th><th>Peran</th><th>Status</th><th>Login terakhir</th><th></th></tr></thead><tbody><?php $__currentLoopData = $admins; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $admin): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><tr><td><b><?php echo e($admin->name); ?></b></td><td><?php echo e($admin->email); ?></td><td><?php echo e(str($admin->role)->title()); ?></td><td><span class="status-pill <?php echo e($admin->is_active ? 'success' : 'neutral'); ?>"><?php echo e($admin->is_active ? 'Aktif' : 'Nonaktif'); ?></span></td><td><?php echo e($admin->last_login_at?->format('d M Y, H.i') ?: '-'); ?></td><td><form method="POST" action="<?php echo e(route('admin.admins.update',$admin)); ?>"><?php echo csrf_field(); ?> <?php echo method_field('PATCH'); ?><input name="name" value="<?php echo e($admin->name); ?>"><input name="email" value="<?php echo e($admin->email); ?>"><select name="role"><option value="admin" <?php if($admin->role === 'admin'): echo 'selected'; endif; ?>>Admin</option><option value="production" <?php if($admin->role === 'production'): echo 'selected'; endif; ?>>Produksi</option><option value="finance" <?php if($admin->role === 'finance'): echo 'selected'; endif; ?>>Finance</option><option value="owner" <?php if($admin->role === 'owner'): echo 'selected'; endif; ?>>Owner</option></select><label><input name="is_active" value="1" type="checkbox" <?php if($admin->is_active): echo 'checked'; endif; ?>> Aktif</label><button class="table-link">Simpan</button></form><?php if($admin->id !== auth()->id()): ?><form method="POST" action="<?php echo e(route('admin.admins.destroy',$admin)); ?>" onsubmit="return confirm('Hapus akun admin <?php echo e($admin->name); ?> secara permanen?')"><?php echo csrf_field(); ?> <?php echo method_field('DELETE'); ?><button class="table-link danger-link">Hapus</button></form><?php endif; ?></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></tbody></table></div></section>
